/**
 * Scoring, version 1.
 *
 * **Do not edit this file to change a formula.** Copy it to `v2.ts` and change
 * that. Runs record the `scoring_version` they were computed under, so an old
 * report has to stay explainable — editing v1 in place would silently rewrite
 * the meaning of every score already shown to a customer.
 *
 * Scores are derived from raw facts, never from a count of findings: "you have
 * 9 problems" is not a measurement, and it would move whenever a rule was
 * added.
 */
import type { SiteFacts } from "../rules/context.ts";
import { fetchedPages, ownPages, servicePages } from "../rules/context.ts";
import { conversionChecks } from "../rules/conversion.ts";

export const SCORING_VERSION = 1;

export interface Scores {
  overall: number;
  technical: number;
  onpage: number;
  conversion: number;
  local: number;
  content: number;
  visibility: number;
}

/** Weights: conversion and local first — fastest to fix, and what we sell. */
export const WEIGHTS = {
  conversion: 0.25,
  local: 0.25,
  content: 0.20,
  visibility: 0.15,
  onpage: 0.10,
  technical: 0.05,
} as const;

export interface ScoringInput extends SiteFacts {
  /** GBP facts (M4). Absent until then. */
  gbp?: {
    exists: boolean;
    verified: boolean;
    reviews: number;
    replyRatePercent: number;
    lastPhotoDaysAgo: number | null;
    infoCompletenessPercent: number;
    competitorAverageReviews: number | null;
  };
  /** Ranking facts (M3). Absent until then. */
  visibility?: {
    keywordsChecked: number;
    inTop10: number;
    inTop3: number;
  };
  /** Competitor page counts (M3). Absent until then. */
  competitorPageCounts?: { servicePages: number[]; articles: number[] };
}

export function score(input: ScoringInput): Scores {
  const technical = technicalScore(input);
  const onpage = onpageScore(input);
  const conversion = conversionScore(input);
  const local = localScore(input);
  const content = contentScore(input);
  const visibility = visibilityScore(input);

  const overall =
    conversion * WEIGHTS.conversion +
    local * WEIGHTS.local +
    content * WEIGHTS.content +
    visibility * WEIGHTS.visibility +
    onpage * WEIGHTS.onpage +
    technical * WEIGHTS.technical;

  return {
    overall: round(overall),
    technical: round(technical),
    onpage: round(onpage),
    conversion: round(conversion),
    local: round(local),
    content: round(content),
    visibility: round(visibility),
  };
}

// ---------------------------------------------------------------------------
export function technicalScore(f: ScoringInput): number {
  const psiScores = f.psi.map((p) => p.performanceScore).filter((n): n is number => n !== null);
  const psi = psiScores.length ? avg(psiScores) : 50; // unmeasured: neutral, not zero

  const pages = fetchedPages(f);
  const indexRatio = pages.length
    ? pages.filter((p) => !p.isNoindex).length / pages.length
    : 1;
  const mobileOk = pages.length
    ? pages.filter((p) => p.hasViewport).length / pages.length
    : 1;

  return clamp(
    0.4 * psi + 0.2 * indexRatio * 100 + 0.2 * (f.https ? 100 : 0) + 0.2 * mobileOk * 100,
  );
}

export function onpageScore(f: ScoringInput): number {
  const pages = fetchedPages(f);
  if (pages.length === 0) return 0;

  const services = servicePages(f);
  const checks: number[] = [
    share(pages, (p) => p.h1Count === 1),
    share(pages, (p) => p.titleLen >= 20 && p.titleLen <= 60),
    share(pages, (p) => Boolean(p.metaDesc)),
    // Only service pages carry a content-length expectation; an about page is
    // allowed to be short. With no service pages the check is not applicable.
    services.length ? share(services, (p) => p.wordCount >= 300) : 1,
    share(pages, (p) => p.schemaTypes.length > 0),
  ];
  return clamp(avg(checks) * 100);
}

export function conversionScore(f: ScoringInput): number {
  const { passed, total } = conversionChecks(f);
  if (total === 0) return 0;
  return clamp((passed / total) * 100);
}

export function localScore(f: ScoringInput): number {
  const g = f.gbp;
  // Before M4 there is no GBP data. Returning 0 would report a failure that was
  // never measured; 50 says "unknown" without inventing a result.
  if (!g) return 50;
  if (!g.exists) return 0;

  const reviewRatio =
    g.competitorAverageReviews && g.competitorAverageReviews > 0
      ? Math.min(1, g.reviews / g.competitorAverageReviews)
      : g.reviews > 0
        ? 1
        : 0;

  const freshness =
    g.lastPhotoDaysAgo === null ? 0 : Math.max(0, 1 - g.lastPhotoDaysAgo / 90);

  return clamp(
    0.3 * (g.verified ? 100 : 40) +
      0.2 * reviewRatio * 100 +
      0.2 * g.replyRatePercent +
      0.15 * freshness * 100 +
      0.15 * g.infoCompletenessPercent,
  );
}

export function contentScore(f: ScoringInput): number {
  const ours = servicePages(f).length;
  const counts = f.competitorPageCounts?.servicePages ?? [];
  // Before M3 there is nothing to compare against.
  if (counts.length === 0) return ours > 0 ? 50 : 0;
  const competitorAvg = avg(counts);
  if (competitorAvg <= 0) return ours > 0 ? 100 : 0;
  return clamp(Math.min(100, (ours / competitorAvg) * 100));
}

export function visibilityScore(f: ScoringInput): number {
  const v = f.visibility;
  if (!v || v.keywordsChecked === 0) return 0; // not ranking is a real result
  return clamp((v.inTop10 / v.keywordsChecked) * 60 + (v.inTop3 / v.keywordsChecked) * 40);
}

// ---------------------------------------------------------------------------
function share<T>(items: T[], ok: (item: T) => boolean): number {
  if (items.length === 0) return 1;
  return items.filter(ok).length / items.length;
}

function avg(ns: number[]): number {
  if (ns.length === 0) return 0;
  return ns.reduce((a, b) => a + b, 0) / ns.length;
}

function clamp(n: number): number {
  return Math.max(0, Math.min(100, n));
}

function round(n: number): number {
  return Math.round(n);
}

/** Everything scoring looked at, so a report can show its working. */
export function scoreInputs(f: ScoringInput) {
  return {
    scoring_version: SCORING_VERSION,
    pages_total: ownPages(f).length,
    pages_fetched: fetchedPages(f).length,
    service_pages: servicePages(f).length,
    psi_measured: f.psi.length,
    https: f.https,
    has_sitemap: f.hasSitemap,
    has_gbp_data: Boolean(f.gbp),
    has_visibility_data: Boolean(f.visibility),
    has_competitor_data: Boolean(f.competitorPageCounts),
  };
}
